function isCommonHostelIssue(description){const text=description.toLowerCase();if(/\b(my room|my bathroom|my personal|individual room|room no\.?\s*\w+|room\s+[a-z]?-?\d+|in my room|personal complaint)\b/.test(text))return false;return /\b(hostel food|food|mess|insect|cockroach|contaminat|poison|water leakage|water leak|drainage|sewer|common bathroom|shared bathroom|hostel electricity|common electricity|power outage|hostel cleaning|common area|hostel facility|hostel maintenance|in the hostel|our hostel|hostel common)\b/.test(text)}
function hostelIssueKey(description){const text=description.toLowerCase();if(/food|mess/.test(text))return 'food';if(/drainage|sewer/.test(text))return 'drainage';if(/water|leak/.test(text))return 'water';if(/electric|power/.test(text))return 'electricity';if(/bathroom|toilet/.test(text))return 'bathroom';if(/clean/.test(text))return 'cleaning';return 'common'}
const activeRequestStatuses=new Set(['Submitted','Assigned','In progress','Escalated to HOD']);
function requestSimilarity(a,b){const words=s=>new Set(s.toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(w=>w.length>2&&!/^(the|and|for|our|with|not|are|was|from|this|that|classroom|problem|issue|please|is|in|my|to|a)$/.test(w)));const left=words(`${a.title} ${a.description}`),right=words(`${b.title} ${b.description}`);if(!left.size||!right.size)return false;const common=[...left].filter(w=>right.has(w));return common.length>=2||common.length===1&&common[0].length>=7}
function matchingActiveRequest(draft,user,requests){const sectionCode=s=>String(s||'').trim().split(/[·|]/).pop().trim().replace(/^Section\s*/i,'');return requests.find(r=>activeRequestStatuses.has(r.status)&&r.category.toLowerCase()===draft.category.toLowerCase()&&r.department===user.dept&&String(r.year||user.year)===String(user.year)&&sectionCode(r.section||user.section)===sectionCode(user.section||user.sectionLabel)&&r.reg!==user.reg&&requestSimilarity(r,draft))}
const percent = (agree,disagree) => agree+disagree ? Math.round(agree/(agree+disagree)*100) : 0;
