function priorityFor(category, title='', description='', studentType=''){const t=`${title} ${description}`.toLowerCase();const hostel=category.toLowerCase().includes('hostel')||studentType==='Hosteller';const transport=category.toLowerCase().includes('transport');if(hostel){if(/electricity.{0,35}(water|shock|wire)|electric.{0,35}(shock|risk|leakage)|shock risk|exposed.{0,25}(wire|electrical)|wire.{0,25}(exposed|water)|water.{0,35}(electrical|electric|wire|shock)|contaminat|poison|insect|cockroach|worm.{0,20}food/.test(t))return 'Emergency';if(/food|menu|tasty|taste|like/.test(t)&&!/insect|cockroach|worm|contaminat|poison/.test(t))return 'Low';if(/tap.{0,30}(drip|drop)|minor.{0,20}(leak|drip)|small.{0,20}(drop|leak)/.test(t))return 'Low';if(/electric|electricity|fan|light|power|leak|water|drainage|sewer|bathroom|maintenance/.test(t))return /flood|large|continuous|overflow|severe|major|unsafe|damage/.test(t)?'Medium':'Medium';return 'Low'}if(transport){if(/bus|route|road|transport|puncture/.test(t)&&(/exam|unsafe|danger|flood|waterlog|heavy rain|cannot safely|emergency/.test(t)))return 'Emergency';if(/seat|damage|broken|puncture|bus/.test(t))return 'Medium';return 'Low'}if(/emergency|urgent|unsafe|danger|injur|fire|exam today|locked out|medical emergency/.test(t))return 'Emergency';if(category==='ID card problem'||/today|tomorrow|exam|class|unable|impact|deadline/.test(t))return 'Medium';return 'Low'}
