 function attendanceValue(student){const marked=attendance.filter(r=>r.reg===student.reg);const base=Number(student.attendance||0);return marked.length?Math.round((base*100+marked.filter(r=>r.status==='Present').length*100)/(100+marked.length)):base}
 function submitAttendance(records){if(role!=='faculty')return;const allowed=students.filter(s=>facultyManages(user,s)).map(s=>s.reg);if(records.some(r=>!allowed.includes(r.reg)))return;const map=new Map(attendance.map(r=>[`${r.reg}|${r.date}`,r]));records.forEach(r=>map.set(`${r.reg}|${r.date}`,r));saveAttendance([...map.values()]);setToast('Attendance saved · student profiles updated');setTimeout(()=>setToast(''),3000)}
